// This code is for n8n's Function node
// The input data is already at the tweets level: $input.first().json.tweets

// Get the tweets array directly
const tweets = $input.first().json.body.tweets;
const outputTweets = [];

// Process each main tweet
if (tweets && Array.isArray(tweets)) {
  tweets.forEach(tweet => {
    // Combine thread content if this is a thread
    let combinedText = tweet.normalized_text || tweet.original_text || "";

    if (tweet.is_thread && tweet.thread_tweets && Array.isArray(tweet.thread_tweets)) {
      // Skip the first tweet if it's the same as the main tweet
      const threadsToAdd = tweet.thread_tweets.filter(t => 
        t.tweet_id !== tweet.tweet_id
      );

      // Add each thread text to the combined content
      if (threadsToAdd.length > 0) {
        combinedText += "\n\n-- THREAD CONTINUATION --\n\n";
        combinedText += threadsToAdd
          .map(t => t.original_text || "")
          .join("\n\n-- NEXT THREAD PART --\n\n");
      }
    }

    // Create a cleaned tweet object with combined thread content
    const extractedTweet = {
      tweet_id: tweet.tweet_id,
      url: tweet.url,
      original_text: tweet.original_text,
      combined_text: combinedText, // Combined thread content
      author_username: tweet.author?.username,
      author_name: tweet.author?.name,
      author_profile_picture: tweet.author?.profile_image,
      media_url: tweet.media,
      timestamp: tweet.timestamp,
      metrics: {
        reply_count: tweet.metrics?.reply_count || 0,
        retweet_count: tweet.metrics?.retweet_count || 0,
        like_count: tweet.metrics?.like_count || 0
      },
      is_thread: tweet.is_thread,
      top_replies: []
    };

    // Process top replies as a list
    if (tweet.top_replies && Array.isArray(tweet.top_replies)) {
      extractedTweet.top_replies = tweet.top_replies.map(replyTweet => ({
        tweet_id: replyTweet.tweet_id,
        url: replyTweet.url,
        original_text: replyTweet.original_text,
        normalized_text: replyTweet.normalized_text,
        author_username: replyTweet.author?.username,
        author_name: replyTweet.author?.name,
        author_profile_picture: replyTweet.author?.profile_image,
        media_url: replyTweet.media,
        timestamp: replyTweet.timestamp,
        metrics: {
          reply_count: replyTweet.metrics?.reply_count || 0,
          retweet_count: replyTweet.metrics?.retweet_count || 0,
          like_count: replyTweet.metrics?.like_count || 0
        }
      }));
    }

    outputTweets.push(extractedTweet);
  });
}

// Return the extracted tweets as new items for n8n

return outputTweets.map(tweet => ({json: tweet}));

