function cleanTweetData(inputJson) {
  // Handle potential missing fields with defaults
  const author_name = inputJson.author_name || '';
  const author_username = inputJson.author_username || '';
  const timestamp = inputJson.timestamp || new Date().toISOString();
  const content = inputJson.combined_text;
  const metrics = inputJson.metrics || { reply_count: 0, retweet_count: 0, like_count: 0 };
  const top_replies = inputJson.top_replies || [];

  // Create main tweet object
  const mainTweet = {
    author: `${author_name} (@${author_username})`,
    date: new Date(timestamp).toLocaleDateString('en-US', {
      month: 'long',
      day: 'numeric',
      year: 'numeric'
    }),
    content: content,
    metrics: {
      replies: metrics.reply_count,
      retweets: metrics.retweet_count,
      likes: metrics.like_count
    }
  };

  // Process replies
  const replies = top_replies.map(reply => ({
    author: `${reply.author_name || ''} (@${reply.author_username || ''})`,
    content: reply.original_text 
  }));

  // Create and return the final object
  return {
    main_tweet: mainTweet,
    replies: replies
  };
}

