// For n8n, use this function with your specific input paths
const analysisResults = $input.first()?.json?.output?.analysis_results;
const tweetData = $('Loop Over Items2').first()?.json;
const result = transformTweetData(analysisResults, tweetData);
return result;

// Function to transform tweet data including replies
function transformTweetData(analysisResults, tweetData) {
  if (!analysisResults || !tweetData) return [];

  const mainTweetId = tweetData?.tweet_id;
  const transformedData = [];

  // Transform main tweet
  const mainTweet = {
    postId: mainTweetId,
    author: {
      name: tweetData?.author_name,
      username: "@" + tweetData?.author_username,
      avatar: tweetData?.author_profile_picture,
      platform: "twitter"
    },
    content: tweetData?.combined_text,
    timestamp: tweetData?.timestamp,
    engagement: {
      likes: tweetData?.metrics?.like_count,
      shares: tweetData?.metrics?.retweet_count,
      comments: tweetData?.metrics?.reply_count
    },
    sentimentAnalysis: {
      result: analysisResults?.main_tweet?.analysis?.sentiment?.label?.toUpperCase(),
      score: analysisResults?.main_tweet?.analysis?.sentiment?.score,
      indicators: analysisResults?.main_tweet?.analysis?.sentiment?.indicators
    },
    emotionAnalysis: {
      primary: analysisResults?.main_tweet?.analysis?.emotion?.primary,
      secondary: analysisResults?.main_tweet?.analysis?.emotion?.secondary,
      intensity: analysisResults?.main_tweet?.analysis?.emotion?.intensity,
      indicators: analysisResults?.main_tweet?.analysis?.emotion?.indicators
    },
    motivationAnalysis: {
      type: analysisResults?.main_tweet?.analysis?.motivation?.type,
      confidenceScore: analysisResults?.main_tweet?.analysis?.motivation?.confidence_score,
      indicators: analysisResults?.main_tweet?.analysis?.motivation?.indicators
    },
    url: tweetData?.url,
    mediaUrls: tweetData?.media_url,
    location: null,
    keyword: $('Webhook1').first().json.body.job_id.match(/^(.*?)min_replies/)[1].trim(),
    original: tweetData?.original_text,
    relatedPostId: null
  };

  transformedData.push(mainTweet);

  // Transform each reply
  if (tweetData?.top_replies?.length > 0) {
    for (let i = 0; i < tweetData.top_replies.length; i++) {
      const reply = tweetData.top_replies[i];
      const replyAnalysis = analysisResults?.replies_analysis?.[i];

      const transformedReply = {
        postId: reply?.tweet_id,
        author: {
          name: reply?.author_name,
          username: "@" + reply?.author_username,
          avatar: reply?.author_profile_picture,
          platform: "twitter"
        },
        content: reply?.normalized_text,
        timestamp: reply?.timestamp,
        engagement: {
          likes: reply?.metrics?.like_count,
          shares: reply?.metrics?.retweet_count,
          comments: reply?.metrics?.reply_count
        },
        sentimentAnalysis: {
          result: replyAnalysis?.analysis?.sentiment?.label?.toUpperCase(),
          score: replyAnalysis?.analysis?.sentiment?.score,
          indicators: replyAnalysis?.analysis?.sentiment?.indicators
        },
        emotionAnalysis: {
          primary: replyAnalysis?.analysis?.emotion?.primary,
          secondary: replyAnalysis?.analysis?.emotion?.secondary,
          intensity: replyAnalysis?.analysis?.emotion?.intensity,
          indicators: replyAnalysis?.analysis?.emotion?.indicators
        },
        motivationAnalysis: {
          type: replyAnalysis?.analysis?.motivation?.type,
          confidenceScore: replyAnalysis?.analysis?.motivation?.confidence_score,
          indicators: replyAnalysis?.analysis?.motivation?.indicators
        },
        url: reply?.url,
        mediaUrls: reply?.media_url,
        location: null,
        keyword:  $('Webhook1').first().json.body.job_id.match(/^(.*?)min_replies/)[1].trim(),
        original: reply?.original_text,
        relatedPostId: mainTweetId
      };

      transformedData.push(transformedReply);
    }
  }

  return transformedData;
}
